  "claims": [
    {
      "claim": "C29 is the most transferable direct outcome: a benzamidine-containing zwitterionic carboxylate had absolute oral bioavailability not high enough for oral use in humans, supporting F below 20% for this structural class.",
      "card_ids": ["C29"]
    },
    {
      "claim": "C202 and C194 show human jejunal effective permeability of 0.013 and 0.03 x10^-4 cm/s for enalaprilat and inogatran, both zwitterionic peptidomimetics resembling the query, indicating extremely poor intestinal absorption.",
      "card_ids": ["C202", "C194"]
    },
    {
      "claim": "C183, C190, C216, and C179 show inogatran efflux ratios of 2.5 to 3.3 in Caco-2, and C186 shows a related poorly permeable compound with efflux ratio 46, demonstrating gut-wall efflux adds to the passive permeability deficit in this class.",
      "card_ids": ["C183", "C190", "C216", "C179", "C186"]
    },
    {
      "claim": "C188 and C205 show enalaprilat permeability was not increased by water absorption or hypotonic perfusion, so paracellular and transcellular routes both remain poor for the zwitterionic active form.",
      "card_ids": ["C188", "C205"]
    },
    {
      "claim": "C189 shows the benzamidine active dabigatran is not a P-gp substrate, a limited counterpoint, but it does not overcome the very low passive permeability and efflux evidence for the query class.",
      "card_ids": ["C189"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C183", "C190", "C216", "C179", "C186", "C194", "C202", "C188", "C205", "C189", "C217", "C211"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental F record for the query molecule itself was supplied.",
    "C29 provides only a qualitative low-F statement, not a numeric F value.",
    "No query-specific gut-wall efflux or intestinal metabolism measurement is available.",
    "No data on active uptake transporters that could offset poor passive permeability were supplied.",
    "No fasted-state-specific oral bioavailability measurement for the query is available.",
    "Human jejunal P_eff records come from enalaprilat and inogatran, not from the query molecule."
  ],
  "decision_summary": "Prediction remains low and is strengthened. L5 adds human jejunal permeability of 0.013 to 0.03 x10^-4 cm/s for zwitterionic peptidomimetics enalaprilat and inogatran, Caco-2 efflux ratios of 2.5 to 3.3 for inogatran and 46 for a related compound, and no paracellular enhancement for enalaprilat. The query combines a benzamidine with a zwitterionic glycine-azetidine-cyclohexyl scaffold, fully ionized at pH 7.4 with logD -7.48. C29 directly reports low oral bioavailability for the benzamidine zwitterion class. The L5 mechanistic evidence affirmatively supports F below 20%."
}

